// Preserve Android evidence separately from isolated local renderer screenshots.
const fs=require('node:fs'),path=require('node:path'),vm=require('node:vm');
const sharp=require(process.env.YAMB_SHARP_PATH||'sharp');
const {resolve}=require('../www/theme-quality-assets.js');
const root=path.resolve(__dirname,'..'),raw=path.join(root,'tmp/emulator-daily-2026-10-29'),local=path.join(root,'tmp/daily-layout-runtime'),out=path.join(root,'docs/theme-visual-audit/emulator-daily-2026-10-29');
const themes=['dark','light','medium','winter','neon','amethyst','easter','desert','moon','severna'];
const names=['Zelena','Svetlo zlato','Trula višnja','Plavi okean','Neon Cyber','Kraljevski ametist','Vaskršnja','Pustinjsko staklo','Mesečev sjaj','Severna maglina'];
const roles=['room','task','complete','already-played','reward-video','ducat'];
const Daily=vm.runInNewContext(fs.readFileSync(path.join(root,'www/dnevniizazov.js'),'utf8')+';DnevniIzazov',{window:{},globalThis:{resolveThemeQualityAsset:resolve}}),daily=Object.create(Daily.prototype);
const entries=themes.map((theme,i)=>({theme,source:theme==='dark'?'dark-daily-active':`${theme}-daily-reentry`,file:`${theme}-reentry`,kind:'android',title:`${names[i]} — stvarni ponovni ulazak / već odigrano`}));
for(const theme of themes.slice(2))entries.push({theme,source:`${theme}-daily-${['medium','winter'].includes(theme)?'enter':'intro'}`,file:`${theme}-intro`,kind:'android',title:`${names[themes.indexOf(theme)]} — kadar intra (ne merenje trajanja)`});
entries.push({theme:'extra',source:'desert-settings-first-switch',file:'desert-close-delayed',kind:'android',title:'Pustinjsko staklo — X još nije učitan'},
 {theme:'extra',source:'desert-settings-ready',file:'desert-close-ready',kind:'android',title:'Isti prikaz nakon učitavanja X'},
 {theme:'extra',source:'dark-main-restored-original',file:'dark-main-restored',kind:'android',title:'Vraćena Zelena i originalne mere emulatora'});
for(const theme of themes)for(const state of ['active','complete','already'])entries.push({theme,source:`${theme}-${state}`,file:`local-${theme}-${state}`,kind:'local',title:`${names[themes.indexOf(theme)]} — lokalni test: ${state}`});
const results=themes.map((theme,i)=>({theme,name:names[i],android:'Pregledan intro/ponovni ulazak i obaveštenje na 360×780; današnji izazov već odigran.',local:'Aktivan panel, završni panel, već odigrano, nagradna i serverska poruka: sintetički podaci u stvarnim Daily/Modal rendererima na tri veličine.',roles:roles.map(role=>({role,primary:'www/'+resolve(daily.getDailyAsset(role,theme)).split('?')[0],status:'prihvatljiv',reason:'Kanonski PNG aktivne teme; u pregledanim PNG/renderima nema nove potrebe za crtanjem. Reentry/room Android dokaz, ostale uloge dodatno lokalni renderer.'})),evidence:entries.filter(e=>e.theme===theme).map(e=>e.file+'.jpg')}));
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
async function main(){
 fs.mkdirSync(out,{recursive:true});
 const test=JSON.parse(fs.readFileSync(path.join(local,'report.json'),'utf8'));
 if(test.rows.length!==150||test.failures.length)throw Error('Successful 150-case Daily runtime report required');
 const report={date:'2026-10-29',room:'Dnevni izazov',scope:'Android emulator: svih deset tema, stvarno obaveštenje već odigrano na 360×780; osam sačuvanih intro kadrova. Nalogu je današnji izazov već odigran, zato nov aktivni/završni tok i isplata nisu izvršeni.',deployment:'Korisnik je potvrdio commit/deploy prethodnih izmena. Javni theme-tournament-final.css?v=3 odgovara lokalnom fajlu. Snimci Androida su PRE novih R22/R23 dorada, koje nisu commitovane/deployovane.',
 findings:{R22:'Daily obaveštenja dobijaju svoj modal-context-daily: jednake Green mere/fontovi naslova, teksta i dugmeta, bez stare Easter razlike od2px. Paletne površine/mastilo i jasno dugme U REDU, bez starog crnog teksta na tamnobraon/plavoj podlozi ili nasleđenih senki devet tema. Dva Green akcijska gradijenta koriste postojeće tamnije tonove radi kontrasta najmanje5,46:1 za tekst. Funkcije i PNG crteži nisu menjani.',R23:'Priprema X učitavala close-v1.png?v=1, a prikazani CSS ?v=3 odnosno?v=4. Resolver sada vraća isti URL i verziju kao CSS svih deset tema, da se pripremljena slika zaista koristi. Regresioni test poredi svih deset punih URL-ova. Android potvrda čeka deploy.',versions:'Daily CSSv4, dnevniizazov.jsv3.4, theme-game-header.jsv5.'},
 tests:{runtime:'PASS150:10tema×5stanja×320×568/360×780/412×915. Stvarni DnevniIzazov, ModalManager i YambFeatures; sintetički posedovani tematski skin, šest učitanih PNG kockica, jednake Green mere/fontovi, bez odsecanja/skrola, vidljivi PNG.',noticeButtonContrastMinimum:Math.min(...test.rows.filter(r=>r.noticeContrast).map(r=>r.noticeContrast)),static:'PASS Daily šest različitih aktivnih RGBA PNG uloga po temi, kanonska ponovna upotreba, intro konfiguracija, reentry, priprema novih slika. PASS Game Header i Settings regresije.',limit:'Izolovani test nema nalog, server ni spoljašnju mrežu; nema oglasa/isplate. Animacije isključene, Montserrat može koristiti offline fallback. Ne meri fizički S25 ili fps.'},
 inventory:'Šest semantičkih PNG uloga po temi =60 različitih fajlova u Daily inventaru. Dukat i reward-video isti su kanonski identiteti kao u drugim sobama. PNG pozadina i odabrani univerzalni/tematski skin su deljeni resursi i vode se odvojeno.',
 switching:'Devet izbora posedovanih tema i vraćanje Zelene uspeli su iz prvog pokušaja. Pustinjsko staklo imalo je prazno X pre naknadnog učitavanja, pa trenutno hladno učitavanje nije potvrđeno; R23 rešava uočeno neslaganje URL-ova, ne tvrdi da je svako mrežno kašnjenje otklonjeno.',
 safety:'Korisnik je odobrio zaustavljanje šest kockica bez reklame/nagrade; nalog je već odigrao izazov i taj test nije korišćen. Nisu zaustavljane nove kockice, preuzimane nagrade, gledane nagradne reklame, menjani skinovi, kupovano ili slati pozivi/poruke. Otvarana su i zatvarana samo informativna stanja.',
 restoration:'Zelena i originalnih1440×3120/560dpi vraćeni, prijava očuvana. Nema novog commita/deploya.',
 limits:['Aktivan i završni Daily panel nisu novi Android dokaz; imaju lokalni sintetički renderer dokaz u svih deset tema. Stvarna reklama/isplata i oporavak nakon greške nisu sada testirani na nalogu.','Precizno trajanje intra nije mereno screenshotima; zajednička konfiguracija ostaje2400/3200ms.','Nove R22/R23 izmene zahtevaju korisnikov deploy i Android potvrdu. Ranijih deset soba nije ponovo kompletno pregledano posle ovog deploya.','Preostaju četiri igračka moda i ove otvorene Daily transakcione/Android provere. Ne označavati svih15soba ili sve tokove kao završene.'],results,entries};
 fs.copyFileSync(path.join(local,'report.json'),path.join(out,'local-layout-report.json'));
 for(const e of entries)await sharp(path.join(e.kind==='android'?raw:local,e.source+'.png')).resize({width:e.kind==='android'?540:360}).jpeg({quality:88,chromaSubsampling:'4:4:4'}).toFile(path.join(out,e.file+'.jpg'));
 fs.writeFileSync(path.join(out,'report.json'),JSON.stringify(report,null,2)+'\n');
 const card=e=>`<article><h3>${esc(e.title)}</h3><a href="${e.file}.jpg"><img loading="lazy" src="${e.file}.jpg" alt="${esc(e.title)}"></a></article>`;
 fs.writeFileSync(path.join(out,'index.html'),`<!doctype html><html lang="sr"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Dnevni izazov — provera29.10.</title><style>*{box-sizing:border-box}body{font:16px/1.5 system-ui;background:#14232e;color:#edf5fc;margin:0;padding:24px}main{max-width:1500px;margin:auto}a{color:#afe4ff}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:16px}article{background:#233847;border:1px solid #7997a9;border-radius:12px;padding:12px}img{width:100%;height:auto}h3{font-size:17px}nav{display:flex;gap:12px;flex-wrap:wrap}</style><main><h1>Dnevni izazov —29.10.2026.</h1><p>${esc(report.scope)}</p><p><b>${esc(report.deployment)}</b></p><nav><a href="report.json">Putanje i rezultati</a><a href="local-layout-report.json">150lokalnih slučajeva</a>${results.map(r=>`<a href="#${r.theme}">${esc(r.name)}</a>`).join('')}</nav><h2>Lokalne dorade</h2><p>${esc(report.findings.R22)}</p><p>${esc(report.findings.R23)}</p><p>${esc(report.tests.runtime)} ${esc(report.tests.limit)}</p><ul>${report.limits.map(s=>`<li>${esc(s)}</li>`).join('')}</ul>${results.map(r=>`<section id="${r.theme}"><h2>${esc(r.name)}</h2><h3>Stvarni Android — objavljena verzija</h3><div class="grid">${entries.filter(e=>e.theme===r.theme&&e.kind==='android').map(card).join('')}</div><h3>Lokalni renderer — nove dorade, test podaci</h3><div class="grid">${entries.filter(e=>e.theme===r.theme&&e.kind==='local').map(card).join('')}</div></section>`).join('')}<h2>Dodatni dokazi</h2><div class="grid">${entries.filter(e=>e.theme==='extra').map(card).join('')}</div><p>${esc(report.safety)}</p><p>${esc(report.restoration)}</p></main></html>`);
 console.log(`Daily: ${results.length} themes, ${entries.filter(e=>e.kind==='android').length} Android and ${entries.filter(e=>e.kind==='local').length} local screenshots, 150 isolated cases.`);
}
main().catch(e=>{console.error(e);process.exitCode=1;});
